# Dependent multiply-accumulate chains on Cortex-A53. A chain through the
# accumulator can use the MAC forwarding path; a chain through a multiplicand
# cannot and sees the full result latency.

# LLVM-MCA-BEGIN fmla-accumulator
fmla	v0.2s, v1.2s, v2.2s
# LLVM-MCA-END

# LLVM-MCA-BEGIN fmla-accumulator-q
fmla	v0.4s, v1.4s, v2.4s
# LLVM-MCA-END

# LLVM-MCA-BEGIN fmla-multiplicand
fmla	v1.2s, v0.2s, v2.2s
fmla	v0.2s, v1.2s, v2.2s
# LLVM-MCA-END

# LLVM-MCA-BEGIN fmadd-addend
fmadd	d0, d1, d2, d0
# LLVM-MCA-END

# LLVM-MCA-BEGIN fmadd-multiplicand
fmadd	d0, d0, d1, d2
# LLVM-MCA-END

# LLVM-MCA-BEGIN mla-accumulator
mla	v0.8b, v1.8b, v2.8b
# LLVM-MCA-END

# LLVM-MCA-BEGIN mla-accumulator-q
mla	v0.16b, v1.16b, v2.16b
# LLVM-MCA-END

# LLVM-MCA-BEGIN mla-multiplicand
mla	v1.8b, v0.8b, v2.8b
mla	v0.8b, v1.8b, v2.8b
# LLVM-MCA-END

# LLVM-MCA-BEGIN smlal-accumulator
smlal	v0.8h, v1.8b, v2.8b
# LLVM-MCA-END

# LLVM-MCA-BEGIN sqdmlal-accumulator
sqdmlal	v0.4s, v1.4h, v2.4h
# LLVM-MCA-END

